mapper.select:
SELECT event_external_id, scope, model_request_id, payload_hash, block_index
FROM code_session_worker_event_receipts
WHERE workspace_uuid = #{workspaceUUID} AND code_session_uuid = #{codeSessionUUID}
  AND worker_epoch = #{epoch} AND event_external_id = #{eventID}

mapper.delete:
DELETE FROM code_session_worker_event_receipts
WHERE workspace_uuid = #{workspaceUUID} AND code_session_uuid IN (
    SELECT uuid FROM code_sessions WHERE workspace_uuid = #{workspaceUUID} AND session_uuid = #{sessionUUID}
)

mapper.select:
WITH ranked AS (
    SELECT model_request_id, block_index,
           ROW_NUMBER() OVER (PARTITION BY model_request_id ORDER BY id DESC) AS position
    FROM code_session_worker_event_receipts
    WHERE workspace_uuid = #{workspaceUUID} AND code_session_uuid = #{codeSessionUUID}
      AND worker_epoch = #{epoch} AND block_index IS NOT NULL
      AND model_request_id IN
      #{requestID}
)
SELECT model_request_id, block_index FROM ranked WHERE position = 1
